69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
73	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
74	     * address shape rather than full RFC 5322 conformance.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner's email. An email whose domain
81	     * (the part after the {@code @}, compared case-insensitively) is on this blocklist is rejected.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
84	        "mailinator.com",
85	        "tempmail.com",
86	        "guerrillamail.com");
87	
88	    /**
89	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
90	     * owner's id, customer code and registration date so the side-effect can be observed
91	     * independently of the HTTP response.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys and values are
97	     * upper-cased so the mapping is applied after the address has been upper-cased.
98	     */
99	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
100	        "ST", "STREET",
101	        "RD", "ROAD",
102	        "AVE", "AVENUE");
103	
104	    /**
105	     * Maximum number of owners permitted in a single city. Once a city already contains this many
106	     * owners, creating another owner in that city is rejected as a conflict.
107	     */
108	    private static final int CITY_CAPACITY = 50;
109	
110	    /**
111	     * Fixed list of public holidays. A registration date that, after the weekend adjustment, lands on
112	     * one of these dates is rolled forward to the next non-holiday business day.
113	     */
114	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
115	        LocalDate.of(2026, 1, 1),
116	        LocalDate.of(2026, 1, 26),
117	        LocalDate.of(2026, 4, 25),
118	        LocalDate.of(2026, 12, 25),
119	        LocalDate.of(2026, 12, 28));
120	
121	    /**
122	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
123	     * already share the current registration date, creating another owner today is rejected.
124	     */
125	    private static final int DAILY_OWNER_LIMIT = 100;
126	
127	    /**
128	     * Number of owner registrations on a single business day above which a newly created owner is
129	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
130	     * registration date, the surge is signalled in the response; the create itself still succeeds.
131	     */
132	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
133	
134	    /**
135	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
136	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
137	     * a city that is not listed has no known region and accepts any 4-digit postcode.
138	     */
139	    private static final Map<String, String> CITY_REGIONS = Map.of(
140	        "Sydney", "NSW",
141	        "Melbourne", "VIC",
142	        "Brisbane", "QLD");
143	
144	    /**
145	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
146	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
147	     */
148	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
149	        "NSW", new int[] {2000, 2099},
150	        "VIC", new int[] {3000, 3099},
151	        "QLD", new int[] {4000, 4099});
152	
153	    private final ClinicService clinicService;
154	
155	    private final OwnerMapper ownerMapper;
156	
157	    private final PetMapper petMapper;
158	
159	    private final VisitMapper visitMapper;
160	
161	    public OwnerRestControllerV1(ClinicService clinicService,
162	                                 OwnerMapper ownerMapper,
163	                                 PetMapper petMapper,
164	                                 VisitMapper visitMapper) {
165	        this.clinicService = clinicService;
166	        this.ownerMapper = ownerMapper;
167	        this.petMapper = petMapper;
168	        this.visitMapper = visitMapper;
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
174	        Collection<Owner> owners;
175	        if (lastName != null) {
176	            owners = this.clinicService.findOwnerByLastName(lastName);
177	        } else {
178	            owners = this.clinicService.findAllOwners();
179	        }
180	        if (owners.isEmpty()) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
189	        Owner owner = this.clinicService.findOwnerById(ownerId);
190	        if (owner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
194	    }
195	
196	    /**
197	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
198	     * upper-cases the value, and expands common street-type abbreviations word-by-word
199	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
200	     * normalizes to the empty string. The normalized value is what the application stores, returns
201	     * and compares for household detection.
202	     *
203	     * @param address the raw address value from the request, may be {@code null}
204	     * @return the normalized address, or the empty string when none was supplied
205	     */
206	    private String normalizeAddress(String address) {
207	        if (address == null) {
208	            return "";
209	        }
210	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
211	        if (collapsed.isEmpty()) {
212	            return "";
213	        }
214	        String[] tokens = collapsed.split(" ");
215	        StringBuilder normalized = new StringBuilder();
216	        for (int i = 0; i < tokens.length; i++) {
217	            if (i > 0) {
218	                normalized.append(' ');
219	            }
220	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
221	        }
222	        return normalized.toString();
223	    }
224	
225	    /**
226	     * Applies address normalization to whichever address form the request supplied, preferring the
227	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
228	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
229	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
230	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
231	     * appended - so everything downstream that reads {@code address} sees the structured value. When
232	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
233	     * earlier minimal owners backward-compatible.
234	     *
235	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
236	     */
237	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
238	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
239	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
240	            ownerFieldsDto.setAddressLine1(line1);
241	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
242	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
243	                ownerFieldsDto.setAddressLine2(line2);
244	                ownerFieldsDto.setAddress(line1 + " " + line2);
245	            } else {
246	                ownerFieldsDto.setAddressLine2(null);
247	                ownerFieldsDto.setAddress(line1);
248	            }
249	        } else {
250	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
251	        }
252	    }
253	
254	    /**
255	     * Rejects an owner payload that is missing or blank in any required field. The response body's
256	     * {@code errors} array lists the name of each offending field.
257	     *
258	     * @param ownerFieldsDto the owner payload to validate
259	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
260	     */
261	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
262	        List<String> missingFields = new ArrayList<>();
263	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
264	            missingFields.add("firstName");
265	        }
266	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
267	            missingFields.add("lastName");
268	        }
269	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
270	            missingFields.add("address");
271	        }
272	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
273	            missingFields.add("city");
274	        }
275	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
276	            missingFields.add("telephone");
277	        }
278	        if (!missingFields.isEmpty()) {
279	            throw new RequiredFieldsMissingException(missingFields);
280	        }
281	    }
282	
283	    /**
284	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
285	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
286	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
287	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
288	     * region accepts any 4-digit postcode.
289	     *
290	     * @param postcode the raw postcode value from the request, may be {@code null}
291	     * @param city the owner's city, used to look up the region whose range constrains the postcode
292	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
293	     */
294	    private void validatePostcode(String postcode, String city) {
295	        if (postcode == null) {
296	            return;
297	        }
298	        if (!postcode.matches("[0-9]{4}")) {
299	            throw new InvalidFieldsException(List.of("postcode"));
300	        }
301	        String region = CITY_REGIONS.get(city);
302	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
303	        if (range != null) {
304	            int value = Integer.parseInt(postcode);
305	            if (value < range[0] || value > range[1]) {
306	                throw new InvalidFieldsException(List.of("postcode"));
307	            }
308	        }
309	    }
310	
311	    /**
312	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
313	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
314	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
315	     * followed by 8 to 15 digits.
316	     *
317	     * @param telephone the raw telephone value from the request
318	     * @return the E.164 telephone (e.g. {@code +61412345678})
319	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
320	     */
321	    private String normalizeTelephone(String telephone) {
322	        if (telephone == null) {
323	            throw new InvalidFieldsException(List.of("telephone"));
324	        }
325	        String trimmed = telephone.trim();
326	        boolean international = trimmed.startsWith("+");
327	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
328	        String digits;
329	        if (international) {
330	            digits = cleaned.substring(1);
331	        } else {
332	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
333	            digits = "61" + national;
334	        }
335	        if (!digits.matches("[0-9]{8,15}")) {
336	            throw new InvalidFieldsException(List.of("telephone"));
337	        }
338	        requireValidNationalLength(digits);
339	        return "+" + digits;
340	    }
341	
342	    /**
343	     * Country codes with a fixed national-number length, checked longest-prefix first so that
344	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
345	     * digits; the North American Numbering Plan ('1') requires 10.
346	     */
347	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
348	
349	    /**
350	     * Validates that the national number (the E.164 digits after the country code) has the length
351	     * required for its country. Country codes without a known fixed length are left to the general
352	     * E.164 length check.
353	     *
354	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
355	     * @throws InvalidFieldsException if the national number is the wrong length for its country
356	     */
357	    private void requireValidNationalLength(String digits) {
358	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
359	            .filter(entry -> digits.startsWith(entry.getKey()))
360	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
361	            .ifPresent(entry -> {
362	                int nationalLength = digits.length() - entry.getKey().length();
363	                if (nationalLength != entry.getValue()) {
364	                    throw new InvalidFieldsException(List.of("telephone"));
365	                }
366	            });
367	    }
368	
369	    /**
370	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
371	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
372	     * be a syntactically valid address; the accepted value is returned lower-cased.
373	     *
374	     * @param email the raw email value from the request, may be {@code null}
375	     * @return the lower-cased email, or {@code null} when none was supplied
376	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
377	     */
378	    private String normalizeEmail(String email) {
379	        if (email == null || email.isBlank()) {
380	            return null;
381	        }
382	        String trimmed = email.trim();
383	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
384	            throw new InvalidFieldsException(List.of("email"));
385	        }
386	        String normalized = trimmed.toLowerCase(Locale.ROOT);
387	        String domain = normalized.substring(normalized.indexOf('@') + 1);
388	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
389	            throw new InvalidFieldsException(List.of("email"));
390	        }
391	        return normalized;
392	    }
393	
394	    /**
395	     * Rejects an owner that collides with an existing owner on their derived identity key. All
396	     * duplicate detection is consolidated into this single key
397	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
398	     * the former separate telephone, email and household checks.
399	     *
400	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
401	     * share the same normalized telephone. Because the telephone is the leading, always-present part
402	     * of the key, two members of the same household with <em>different</em> telephones have different
403	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
404	     * scenario in the acceptance suite exercises - is rejected.
405	     *
406	     * @param owner the owner being created, with its normalized telephone and email already applied
407	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
408	     */
409	    /**
410	     * Tests whether an existing owner is not soft-deleted, so that duplicate and identity detection
411	     * can ignore owners flagged {@code deleted}. An owner whose {@code deleted} flag is {@code null}
412	     * or {@code false} is considered active; only an explicit {@code true} excludes it.
413	     *
414	     * @param owner an existing owner from the data store
415	     * @return {@code true} when the owner is not flagged deleted, otherwise {@code false}
416	     */
417	    private static boolean isNotDeleted(Owner owner) {
418	        return !Boolean.TRUE.equals(owner.getDeleted());
419	    }
420	
421	    private void requireUniqueIdentity(Owner owner) {
422	        String telephone = owner.getTelephone();
423	        boolean taken = this.clinicService.findAllOwners().stream()
424	            .filter(OwnerRestControllerV1::isNotDeleted)
425	            .map(Owner::getTelephone)
426	            .anyMatch(existing -> existing != null && existing.equals(telephone));
427	        if (taken) {
428	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
429	        }
430	    }
431	
432	    /**
433	     * Rejects an owner that would join an existing owner's household without opting in. The household
434	     * is keyed by the owner's computed {@link OwnerMapper#householdId(Owner) household id} - the first
435	     * 12 hex characters of SHA-256 over the normalized last name and postcode - so two owners sharing
436	     * a last name and postcode belong to the same household even with different addresses or
437	     * telephones. Only owners with a postcode participate: an owner without a postcode has no
438	     * well-defined household and is never blocked here. The check is bypassed by the caller when the
439	     * request sets {@code sharesHousehold}, so a declared household member is created rather than
440	     * rejected.
441	     *
442	     * @param owner the owner being created, with its normalized fields already applied
443	     * @throws DuplicateOwnerHouseholdException if an existing owner already shares the household id
444	     */
445	    private void requireNoHouseholdDuplicate(Owner owner) {
446	        if (owner.getPostcode() == null) {
447	            return;
448	        }
449	        String householdId = ownerMapper.householdId(owner);
450	        boolean taken = this.clinicService.findAllOwners().stream()
451	            .filter(OwnerRestControllerV1::isNotDeleted)
452	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
453	        if (taken) {
454	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getPostcode());
455	        }
456	    }
457	
458	    /**
459	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
460	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
461	     * normalizes to the empty string.
462	     *
463	     * @param value the raw field value, may be {@code null}
464	     * @return the trimmed, whitespace-collapsed, lower-cased form
465	     */
466	    private String normalizeHousehold(String value) {
467	        if (value == null) {
468	            return "";
469	        }
470	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
471	    }
472	
473	    /**
474	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
475	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
476	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
477	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
478	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
479	     * returned so the result is deterministic.
480	     *
481	     * @param owner the owner being created, with its normalized telephone already applied
482	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
483	     */
484	    private Owner findPossibleDuplicate(Owner owner) {
485	        String lastName = owner.getLastName();
486	        String postcode = owner.getPostcode();
487	        if (lastName == null || postcode == null) {
488	            return null;
489	        }
490	        String telephone = owner.getTelephone();
491	        return this.clinicService.findAllOwners().stream()
492	            .filter(OwnerRestControllerV1::isNotDeleted)
493	            .filter(existing -> postcode.equals(existing.getPostcode()))
494	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
495	            .filter(existing -> existing.getTelephone() == null
496	                || !existing.getTelephone().equals(telephone))
497	            .min(Comparator.comparingInt(Owner::getId))
498	            .orElse(null);
499	    }
500	
501	    /**
502	     * Rejects an owner whose city already contains the maximum permitted number of owners
503	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
504	     * the same normalization used for the other owner household fields.
505	     *
506	     * @param city the city of the owner being created
507	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
508	     */
509	    private void requireCityHasCapacity(String city) {
510	        String normalizedCity = normalizeHousehold(city);
511	        long count = this.clinicService.findAllOwners().stream()
512	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
513	            .count();
514	        if (count >= CITY_CAPACITY) {
515	            throw new CityAtCapacityException(city);
516	        }
517	    }
518	
519	    /**
520	     * Rejects creating an owner once the given business day has already reached the maximum
521	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
522	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
523	     * registration date.
524	     *
525	     * @param registrationDate the business-day-adjusted registration date of the owner being created
526	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
527	     *     registered on that business day
528	     */
529	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
530	        long count = this.clinicService.findAllOwners().stream()
531	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
532	            .count();
533	        if (count >= DAILY_OWNER_LIMIT) {
534	            throw new DailyOwnerLimitException(registrationDate);
535	        }
536	    }
537	
538	    /**
539	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
540	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
541	     * been registered on that date. Evaluated before the new owner is persisted, so the count
542	     * reflects the owners that existed at the time of creation.
543	     *
544	     * @param registrationDate the business-day-adjusted registration date of the owner being created
545	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
546	     *     that registration date, otherwise {@code false}
547	     */
548	    private boolean isBulkSignup(LocalDate registrationDate) {
549	        long count = this.clinicService.findAllOwners().stream()
550	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
551	            .count();
552	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
553	    }
554	
555	    /**
556	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
557	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
558	     * date in the future is invalid.
559	     *
560	     * @param registrationDate the registration date supplied on the request, may be {@code null}
561	     * @throws InvalidFieldsException if the supplied date is later than today's server date
562	     */
563	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
564	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
565	            throw new InvalidFieldsException(List.of("registrationDate"));
566	        }
567	    }
568	
569	    /**
570	     * Rolls a registration date forward onto a business day: any Saturday, Sunday or listed public
571	     * holiday is advanced day by day until the first weekday that is not a public holiday, while a
572	     * plain weekday is returned unchanged.
573	     *
574	     * @param date the effective registration date (supplied or defaulted to the server date)
575	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
576	     */
577	    private LocalDate toBusinessDay(LocalDate date) {
578	        LocalDate result = date;
579	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
580	            result = result.plusDays(1);
581	        }
582	        return result;
583	    }
584	
585	    private boolean isWeekend(LocalDate date) {
586	        return switch (date.getDayOfWeek()) {
587	            case SATURDAY, SUNDAY -> true;
588	            default -> false;
589	        };
590	    }
591	
592	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
593	    @Override
594	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
595	        applyAddressFields(ownerFieldsDto);
596	        validateRequiredFields(ownerFieldsDto);
597	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
598	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
599	        requireCityHasCapacity(ownerFieldsDto.getCity());
600	        String email = normalizeEmail(ownerFieldsDto.getEmail());
601	        HttpHeaders headers = new HttpHeaders();
602	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
603	        owner.setTelephone(telephone);
604	        owner.setEmail(email);
605	        owner.setDeleted(false);
606	        requireUniqueIdentity(owner);
607	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
608	        if (!sharesHousehold) {
609	            requireNoHouseholdDuplicate(owner);
610	        }
611	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
612	        LocalDate effectiveDate = owner.getRegistrationDate() != null
613	            ? owner.getRegistrationDate() : LocalDate.now();
614	        LocalDate registrationDate = toBusinessDay(effectiveDate);
615	        owner.setRegistrationDate(registrationDate);
616	        requireDailyLimitNotReached(registrationDate);
617	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
618	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
619	        owner.setPossibleDuplicate(possibleDuplicate != null);
620	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
621	        this.clinicService.saveOwner(owner);
622	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
623	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
624	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
625	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
626	        headers.setLocation(UriComponentsBuilder.newInstance()
627	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
628	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
629	    }
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
634	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
635	        if (currentOwner == null) {
636	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
637	        }
638	        currentOwner.setAddress(ownerFieldsDto.getAddress());
639	        currentOwner.setCity(ownerFieldsDto.getCity());
640	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
641	        currentOwner.setLastName(ownerFieldsDto.getLastName());
642	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
643	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
644	        this.clinicService.saveOwner(currentOwner);
645	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
646	    }
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Transactional
650	    @Override
651	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
652	        Owner owner = this.clinicService.findOwnerById(ownerId);
653	        if (owner == null) {
654	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
655	        }
656	        owner.setDeleted(true);
657	        this.clinicService.saveOwner(owner);
658	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
659	    }
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Override
663	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
664	        Owner owner = this.clinicService.findOwnerById(ownerId);
665	        if (owner == null) {
666	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
667	        }
668	        HttpHeaders headers = new HttpHeaders();
669	        Pet pet = petMapper.toPet(petFieldsDto);
670	        owner.setId(ownerId);
671	        pet.setOwner(owner);
672	        pet.getType().setName(null);
673	        this.clinicService.savePet(pet);
674	        PetDto petDto = petMapper.toPetDto(pet);
675	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
676	            .buildAndExpand(pet.getId()).toUri());
677	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
678	    }
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Override
682	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
683	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
684	        if (currentOwner != null) {
685	            Pet currentPet = this.clinicService.findPetById(petId);
686	            if (currentPet != null) {
687	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
688	                currentPet.setName(petFieldsDto.getName());
689	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
690	                this.clinicService.savePet(currentPet);
691	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
692	            }
693	        }
694	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
695	    }
696	
697	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
698	    @Override
699	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
700	        HttpHeaders headers = new HttpHeaders();
701	        Visit visit = visitMapper.toVisit(visitFieldsDto);
702	        Pet pet = new Pet();
703	        pet.setId(petId);
704	        visit.setPet(pet);
705	        this.clinicService.saveVisit(visit);
706	        VisitDto visitDto = visitMapper.toVisitDto(visit);
707	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
708	            .buildAndExpand(visit.getId()).toUri());
709	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
710	    }
711	
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
716	        Owner owner = this.clinicService.findOwnerById(ownerId);
717	        if (owner != null) {
718	            Pet pet = owner.getPet(petId);
719	            if (pet != null) {
720	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
721	            }
722	        }
723	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
724	    }
725	}
